def closed_lathe(name, prof, mat, segs=72):
    # prof: closed loop of (r,z), first and last on axis (r=0)
    bm = bmesh.new(); rings=[]
    for (r,z) in prof:
        if r == 0: rings.append([bm.verts.new((0,0,z))])
        else: rings.append([bm.verts.new((r*math.cos(2*math.pi*i/segs), r*math.sin(2*math.pi*i/segs), z)) for i in range(segs)])
    for a,b in zip(rings[:-1], rings[1:]):
        for i in range(segs):
            j=(i+1)%segs
            if len(a)==1: bm.faces.new((a[0], b[i], b[j]))
            elif len(b)==1: bm.faces.new((a[i], a[j], b[0]))
            else: bm.faces.new((a[i],a[j],b[j],b[i]))
